-- Migration: Year 3 - Infectious Diseases MCQ Bank (COMPLETE: 1-350)
-- Based on Harrison's 22nd Ed, Step-Up to Medicine 5th Ed, and Pocket Medicine 7th Ed.
-- This file is IDEMPOTENT: It deletes existing ID MCQs before inserting to prevent duplicates.
-- Date: 2026-04-29

BEGIN;

DO $$ 
DECLARE 
    v_topic_id UUID;
BEGIN
    SELECT id INTO v_topic_id FROM topics WHERE slug = 'infectious-disease' LIMIT 1;

    -- PREVENT DUPLICATES: Delete existing MCQs for this specific topic before re-inserting
    DELETE FROM mcqs WHERE topic_id = v_topic_id;

    -- SECTION 1-9: SEPSIS, CNS, ENDOCARDITIS, BACTERIAL
    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '1: "Sepsis" is currently defined as life-threatening organ dysfunction caused by a dysregulated host response to infection, measured by a change in SOFA score of >= ____ points.', '["1", "2", "3", "5"]', 1, 'SOFA = Sequential Organ Failure Assessment. (Harrison''s Ch. 143)'),
    (v_topic_id, '2: "Septic Shock" is a subset of sepsis requiring vasopressors to maintain MAP >= 65 mmHg AND a serum lactate level > ____ mmol/L despite adequate fluid resuscitation.', '["1", "2", "4", "5"]', 1, 'Indicates profound circulatory and cellular/metabolic abnormalities. (Step-Up)'),
    (v_topic_id, '3: The "qSOFA" (quick SOFA) criteria used at the bedside include respiratory rate >= 22, altered mental status, and systolic blood pressure <= ____ mmHg.', '["90", "100", "110", "120"]', 1, 'Designed to quickly identify patients at risk for poor outcomes. (Pocket Medicine)'),
    (v_topic_id, '4: What is the recommended initial fluid resuscitation volume for a patient in septic shock?', '["10 mL/kg", "20 mL/kg", "30 mL/kg", "50 mL/kg"]', 2, 'Crystalloids should be started within the first 3 hours. (Harrison''s Ch. 143)'),
    (v_topic_id, '5: Which vasopressor is the FIRST-LINE choice for septic shock that is refractory to fluid resuscitation?', '["Dopamine", "Epinephrine", "Norepinephrine", "Vasopressin"]', 2, 'Has both alpha and beta-1 activity with less tachycardia than dopamine. (Step-Up)'),
    (v_topic_id, '6: "Toxic Shock Syndrome" (TSS) caused by S. aureus is primarily mediated by which toxin?', '["Exfoliative toxin", "TSST-1 (Superantigen)", "Enterotoxin B", "Alpha-toxin"]', 1, 'Causes massive T-cell activation and cytokine release. (Pocket Medicine)'),
    (v_topic_id, '7: TSS caused by Streptococcus pyogenes (Group A Strep) is often associated with which clinical finding that is RARE in staphylococcal TSS?', '["Fever", "Hypotension", "Necrotizing fasciitis / severe local pain", "Desquamation"]', 2, 'Strep TSS often involves deep tissue infection. (Harrison''s Ch. 153)'),
    (v_topic_id, '8: Blood cultures in Sepsis should ideally be drawn ____ starting antibiotics.', '["Before", "During", "After", "Only if fever > 39C"]', 0, 'To increase the yield of pathogen identification. (Step-Up)'),
    (v_topic_id, '9: "Empiric" antibiotic therapy in sepsis should be started within ____ of recognition.', '["1 hour", "3 hours", "6 hours", "24 hours"]', 0, 'Delays in antibiotics are associated with increased mortality. (Pocket Medicine)'),
    (v_topic_id, '10: A patient with sepsis from an unknown source and a history of IV drug use should have empiric coverage for which organism?', '["H. pylori", "MRSA", "Listeria", "Legionella"]', 1, 'Risk of endocarditis or skin/soft tissue infection. (Harrison''s Ch. 143)'),
    (v_topic_id, '11: What is the most common cause of community-acquired bacterial meningitis in adults?', '["Neisseria meningitidis", "Streptococcus pneumoniae", "Listeria monocytogenes", "Haemophilus influenzae"]', 1, 'Classic association across all ages except neonates. (Harrison''s Ch. 147)'),
    (v_topic_id, '12: "Listeria monocytogenes" meningitis coverage (with Ampicillin) must be added for which adult populations?', '["Age > 50 and immunocompromised", "College students", "Athletes", "Travelers to Asia"]', 0, 'Listeria is more common in the elderly and the suppressed. (Step-Up)'),
    (v_topic_id, '13: The "Classic Triad" of bacterial meningitis includes fever, nuchal rigidity, and:', '["Vomiting", "Altered mental status", "Seizures", "Rash"]', 1, 'However, all three are present in only ~45% of cases. (Pocket Medicine)'),
    (v_topic_id, '14: "Kernig''s Sign" is positive when pain is elicited during:', '["Passive neck flexion", "Passive knee extension when the hip is flexed to 90 degrees", "Straight leg raise", "None"]', 1, 'Sign of meningeal irritation. (Harrison''s Ch. 147)'),
    (v_topic_id, '15: "Brudzinski''s Sign" is positive when passive neck flexion causes:', '["Pain in the back", "Involuntary flexion of the hips and knees", "Headache", "Vomiting"]', 1, 'Indicates severe meningeal inflammation. (Step-Up)'),
    (v_topic_id, '16: In bacterial meningitis, CSF typically shows high protein, low glucose, and high ____.', '["Lymphocytes", "Neutrophils (PMNs)", "Eosinophils", "Monocytes"]', 1, 'CSF glucose < 40 mg/dL is highly suggestive of bacterial etiology. (Pocket Medicine)'),
    (v_topic_id, '17: Which medication should be given BEFORE or with the first dose of antibiotics in suspected S. pneumoniae meningitis to reduce neurological sequelae?', '["Heparin", "Dexamethasone", "Aspirin", "Insulin"]', 1, 'Reduces the inflammatory response to bacterial lysis. (Harrison''s Ch. 147)'),
    (v_topic_id, '18: What is the treatment of choice for close contacts of a patient with Neisseria meningitidis meningitis?', '["Penicillin", "Rifampin (or Ciprofloxacin/Ceftriaxone)", "Vancomycin", "Vaccination only"]', 1, 'Chemoprophylaxis is crucial for close contacts. (Step-Up)'),
    (v_topic_id, '19: "Viral Meningitis" (Aseptic) is most commonly caused by:', '["HSV", "Enteroviruses (Coxsackie/Echovirus)", "HIV", "CMV"]', 1, 'Usually has a benign course compared to bacterial. (Pocket Medicine)'),
    (v_topic_id, '20: "Encephalitis" differs from meningitis primarily by the presence of:', '["Fever", "Altered brain function (confusion, personality changes, seizures)", "Neck stiffness", "High WBC in CSF"]', 1, 'Brain parenchyma is involved in encephalitis. (Harrison''s Ch. 147)'),
    (v_topic_id, '21: What is the most common cause of sporadic, fatal encephalitis in the US?', '["West Nile Virus", "Herpes Simplex Virus-1 (HSV-1)", "Rabies", "Varicella Zoster Virus"]', 1, 'Classically involves the temporal lobes. (Harrison''s Ch. 147)'),
    (v_topic_id, '22: Hemorrhagic necrosis of the temporal lobes on MRI is pathognomonic for:', '["Lyme disease", "HSV Encephalitis", "Stroke", "Tumor"]', 1, 'Requires urgent IV Acyclovir. (Step-Up)'),
    (v_topic_id, '23: "West Nile Encephalitis" is transmitted by mosquitoes and may present with a characteristic:', '["Rash on palms", "Flaccid paralysis (resembling polio)", "Blindness", "Ear pain"]', 1, 'Neuroinvasive disease can cause motor neuron damage. (Pocket Medicine)'),
    (v_topic_id, '24: A "Brain Abscess" with a ring-enhancing lesion on CT in an immunocompetent patient is most commonly caused by ____ and ____.', '["Viridans strep; Staph aureus", "E. coli; Listeria", "HIV; CMV", "None"]', 0, 'Often results from direct spread (sinusitis/otitis) or hematogenous spread. (Harrison''s Ch. 147)'),
    (v_topic_id, '25: In an AIDS patient, multiple ring-enhancing lesions in the brain are most likely:', '["Primary CNS Lymphoma", "Toxoplasmosis", "Cryptococcus", "PML"]', 1, 'Treated empirically with pyrimethamine and sulfadiazine. (Step-Up)'),
    (v_topic_id, '26: "Cryptococcal Meningitis" in HIV patients is diagnosed with which CSF test?', '["Gram stain", "India Ink or Cryptococcal Antigen (CrAg)", "PCR for HSV", "Acid-fast stain"]', 1, 'CrAg is highly sensitive and specific. (Pocket Medicine)'),
    (v_topic_id, '27: What is the treatment of choice for Cryptococcal Meningitis?', '["Fluconazole only", "Amphotericin B + Flucytosine", "Acyclovir", "Penicillin"]', 1, 'Followed by long-term fluconazole suppression. (Harrison''s Ch. 219)'),
    (v_topic_id, '28: "Rabies" is a rhabdovirus transmitted by bites (bats, raccoons, dogs). Once symptoms like ____ appear, it is almost 100% fatal.', '["Cough", "Hydrophobia and laryngeal spasms", "Diarrhea", "Rash"]', 1, 'Post-exposure prophylaxis (PEP) must be given before symptoms start. (Step-Up)'),
    (v_topic_id, '29: "Progressive Multifocal Leukoencephalopathy" (PML) is caused by the reactivation of the ____ virus in immunocompromised patients.', '["EBV", "JC Virus", "BK Virus", "HIV"]', 1, 'Causes demyelination and non-enhancing white matter lesions. (Pocket Medicine)'),
    (v_topic_id, '30: "Subacute Sclerosing Panencephalitis" (SSPE) is a late complication of which childhood infection?', '["Rubella", "Measles", "Mumps", "Varicella"]', 1, 'Occurs years after the initial infection. (Harrison''s Ch. 147)'),
    (v_topic_id, '31: What is the most common cause of Acute Infective Endocarditis on NATIVE valves?', '["Staphylococcus aureus", "Viridans group streptococci", "Enterococcus", "Streptococcus bovis"]', 0, 'Highly virulent and destructive. (Harrison''s Ch. 138)'),
    (v_topic_id, '32: "Viridans group streptococci" (e.g., S. mutans) are the most common cause of ____ endocarditis.', '["Acute", "Subacute", "Prosthetic valve", "IV drug user"]', 1, 'Often follows dental procedures. (Step-Up)'),
    (v_topic_id, '33: What is the most common organism in endocarditis in IV drug users, typically involving the tricuspid valve?', '["Streptococcus", "Staphylococcus aureus", "Candida", "Pseudomonas"]', 1, 'Right-sided endocarditis is common in this population. (Pocket Medicine)'),
    (v_topic_id, '34: "Streptococcus gallolyticus" (formerly S. bovis) endocarditis is strongly associated with which underlying condition?', '["Diabetes", "Colorectal Cancer", "Lung cancer", "Liver failure"]', 1, 'Requires a mandatory colonoscopy. (Harrison''s Ch. 138)'),
    (v_topic_id, '35: "Roth Spots" are a clinical sign of endocarditis and are found in the:', '["Mouth", "Retina (hemorrhage with pale center)", "Fingernails", "Palms"]', 1, 'Due to immune complex-mediated vasculitis. (Step-Up)'),
    (v_topic_id, '36: "Janeway Lesions" are painless, erythematous macules on the palms/soles, representing:', '["Immune complexes", "Septic emboli", "Allergy", "Fungus"]', 1, 'Contrast with Osler nodes which are immune-mediated and painful. (Pocket Medicine)'),
    (v_topic_id, '37: "Osler Nodes" are ____, while "Janeway Lesions" are ____.', '["Painless; Painful", "Painful; Painless", "Itchy; Not itchy", "None"]', 1, '"O"sler = "O"uch. (Harrison''s Ch. 138)'),
    (v_topic_id, '38: The "Duke Criteria" for IE include major criteria such as positive blood cultures and ____.', '["Fever", "Echocardiogram showing vegetation", "Splinter hemorrhages", "High ESR"]', 1, 'Transesophageal Echo (TEE) is more sensitive than TTE. (Step-Up)'),
    (v_topic_id, '39: "HACEK" organisms (Haemophilus, Aggregatibacter, Cardiobacterium, Eikenella, Kingella) are known for causing endocarditis that is:', '["Highly aggressive", "Culture-negative (difficult to grow)", "Only in children", "None"]', 1, 'Fastidious Gram-negative bacilli. (Pocket Medicine)'),
    (v_topic_id, '40: What is the standard antibiotic prophylaxis for high-risk patients undergoing dental procedures?', '["Penicillin", "Amoxicillin (or Clindamycin if allergic)", "Vancomycin", "Ciprofloxacin"]', 1, 'Given 30-60 minutes before the procedure. (Harrison''s Ch. 138)'),
    (v_topic_id, '41: "Staphylococcus aureus" produces "Coagulase," which distinguishes it from:', '["Streptococcus", "Coagulase-negative Staph (e.g., S. epidermidis)", "Enterococcus", "None"]', 1, 'S. aureus is "Staph aureus", others are "CoNS". (Step-Up)'),
    (v_topic_id, '42: "Staphylococcus epidermidis" is a common cause of infection in which setting?', '["Community pneumonia", "Prosthetic devices (valves, joints, catheters)", "Food poisoning", "UTI"]', 1, 'Forms a thick biofilm on foreign material. (Pocket Medicine)'),
    (v_topic_id, '43: "Streptococcus pyogenes" (Group A) is the most common cause of bacterial pharyngitis and can lead to:', '["Rheumatic Fever and Post-Strep Glomerulonephritis", "Liver failure", "Bladder cancer", "None"]', 0, 'Nonsuppurative complications. (Harrison''s Ch. 153)'),
    (v_topic_id, '44: "Erysipelas" is a distinct type of superficial cellulitis with sharp borders, almost always caused by:', '["S. aureus", "Group A Streptococcus", "Pseudomonas", "E. coli"]', 1, 'Involves the upper dermis and superficial lymphatics. (Step-Up)'),
    (v_topic_id, '45: "Streptococcus agalactiae" (Group B) is the leading cause of sepsis and meningitis in:', '["Elderly", "Neonates", "Teens", "Men"]', 1, 'Transmitted from the mother''s vaginal canal during birth. (Pocket Medicine)'),
    (v_topic_id, '46: "Enterococcus" infections (E. faecalis and E. faecium) are often resistant to which class of antibiotics?', '["Penicillins", "Cephalosporins", "Macrolides", "None"]', 1, 'Enterococci are intrinsically resistant to cephalosporins. (Harrison''s Ch. 154)'),
    (v_topic_id, '47: "Anthrax" is caused by Bacillus anthracis. The "Woolsorter''s disease" (inhalation anthrax) classically shows which X-ray finding?', '["Lobar pneumonia", "Widened mediastinum", "Cavity", "Pleural effusion only"]', 1, 'Due to hemorrhagic lymphadenitis. (Step-Up)'),
    (v_topic_id, '48: "Listeria monocytogenes" is unique among Gram-positive bacilli for its ability to grow at ____ temperatures.', '["Body", "Freezing/Cold (4C)", "Boiling", "None"]', 1, 'Found in deli meats and unpasteurized cheese. (Pocket Medicine)'),
    (v_topic_id, '49: "Diphtheria" is characterized by a "grayish pseudomembrane" in the throat and is caused by:', '["Corynebacterium diphtheriae", "Clostridium", "Staphylococcus", "None"]', 0, 'Toxin can cause myocarditis and nerve damage. (Harrison''s Ch. 155)'),
    (v_topic_id, '50: "Actinomyces israelii" causes sulfur granules and abscesses, typically following:', '["Dental work or trauma to the jaw", "Lung infection", "UTI", "None"]', 0, 'Anaerobic, branching Gram-positive rod. (Step-Up)'),
    (v_topic_id, '51: "Neisseria meningitidis" (Meningococcus) classically presents with a ____ rash.', '["Itchy", "Petechial/Purpuric", "Vesicular", "None"]', 1, 'Sign of meningococcemia and DIC (Waterhouse-Friderichsen). (Pocket Medicine)'),
    (v_topic_id, '52: "Neisseria gonorrhoeae" is a common cause of STIs and can lead to "Disseminated Gonococcal Infection" (DGI) presenting with:', '["Blindness", "Tenosynovitis, dermatitis, and polyarthralgia", "Liver failure", "None"]', 1, 'Look for pustular skin lesions and joint pain. (Harrison''s Ch. 161)'),
    (v_topic_id, '53: "Haemophilus influenzae" type b (Hib) was a leading cause of epiglottitis and meningitis in children before the advent of:', '["Antibiotics", "Vaccination", "Steroids", "None"]', 1, 'The Hib conjugate vaccine. (Step-Up)'),
    (v_topic_id, '54: "Legionella pneumophila" is often transmitted via ____ and can cause pneumonia + diarrhea + hyponatremia.', '["Person-to-person", "Aerosolized water (AC units, cooling towers)", "Food", "Ticks"]', 1, 'Diagnosed with a urinary antigen test. (Pocket Medicine)'),
    (v_topic_id, '55: "Pseudomonas aeruginosa" is a common cause of nosocomial infections and is known for producing a ____ pigment.', '["Red", "Blue-green (Pyocyanin)", "Yellow", "Black"]', 1, 'Has a distinct "fruity" odor. (Harrison''s Ch. 169)'),
    (v_topic_id, '56: "Ecthyma gangrenosum" is a black, necrotic skin lesion classically caused by sepsis with:', '["Staph aureus", "Pseudomonas aeruginosa", "E. coli", "Candida"]', 1, 'Often seen in neutropenic patients. (Step-Up)'),
    (v_topic_id, '57: "Bordetella pertussis" causes Whooping Cough. The "paroxysmal stage" involves:', E'["Mild cough", "Severe coughing fits ending in an inspiratory \\"whoop\\"", "Pneumonia", "Fever only"]', 1, 'The "whoop" is more common in children than adults. (Pocket Medicine)'),
    (v_topic_id, '58: "Pasteurella multocida" infection typically follows:', '["Dog or Cat bites", "Cat scratches", "Eating raw fish", "Tick bites"]', 0, 'Requires treatment with Amoxicillin-Clavulanate. (Harrison''s Ch. 170)'),
    (v_topic_id, '59: "Bartonella henselae" is the causative agent of:', '["Cat Scratch Disease", "Rat bite fever", "Lyme disease", "Plague"]', 0, 'Causes regional lymphadenopathy. (Step-Up)'),
    (v_topic_id, '60: "Brucellosis" is often acquired from:', '["Unpasteurized dairy products or contact with livestock", "Water", "Soil", "Mosquitoes"]', 0, 'Presents with an "undulant" (rising and falling) fever. (Pocket Medicine)'),
    (v_topic_id, '61: "Clostridioides difficile" (C. diff) infection is most commonly triggered by:', '["Spicy food", "Recent Antibiotic use (e.g., Clindamycin, Fluoroquinolones)", "Surgery", "Stress"]', 1, 'Disrupts normal gut flora. (Harrison''s Ch. 139)'),
    (v_topic_id, '62: What is the first-line treatment for a first episode of C. diff infection?', '["Metronidazole", "Oral Vancomycin or Fidaxomicin", "IV Vancomycin", "Ciprofloxacin"]', 1, 'Metronidazole is no longer first-line for adults. (Step-Up)'),
    (v_topic_id, '63: "Clostridium tetani" toxin blocks the release of ____ neurotransmitters (GABA/Glycine), leading to spastic paralysis.', '["Excitatory", "Inhibitory", "All", "None"]', 1, 'Presents as "lockjaw" and risus sardonicus. (Pocket Medicine)'),
    (v_topic_id, '64: "Clostridium botulinum" toxin blocks the release of ____ at the NMJ, leading to flaccid paralysis.', '["GABA", "Acetylcholine", "Dopamine", "Serotonin"]', 1, 'Starts with cranial nerves ("Diplopia, Dysphagia, Dysphonia"). (Harrison''s Ch. 157)'),
    (v_topic_id, '65: "Infant Botulism" is often associated with the ingestion of ____ containing spores.', '["Milk", "Honey", "Water", "Apples"]', 1, 'Infants lack the gut flora to inhibit spore germination. (Step-Up)'),
    (v_topic_id, '66: "Gas Gangrene" (Myonecrosis) is caused by:', '["Clostridium difficile", "Clostridium perfringens", "Staphylococcus", "None"]', 1, 'Characterized by rapid tissue destruction and crepitus. (Pocket Medicine)'),
    (v_topic_id, '67: "Tularemia" (Francisella tularensis) is often associated with contact with:', '["Rabbits and ticks", "Dogs", "Birds", "Fish"]', 0, 'Can cause an ulceroglandular or pneumonic syndrome. (Harrison''s Ch. 175)'),
    (v_topic_id, '68: "Plague" is caused by Yersinia pestis and is transmitted by ____.', '["Mosquitoes", "Fleas (from rodents)", "Ticks", "Bites"]', 1, 'Presents as "Bubonic" (painful lymph nodes/buboes) or "Pneumonic." (Step-Up)'),
    (v_topic_id, '69: "Leptospirosis" is transmitted via water contaminated with ____ urine.', '["Human", "Animal (rodents, dogs)", "Bird", "None"]', 1, 'Can cause "Weil''s Disease" (jaundice, renal failure). (Pocket Medicine)'),
    (v_topic_id, '70: "Q Fever" is caused by Coxiella burnetii and is often seen in:', '["Fishermen", "Farmers/Veterinarians (contact with livestock/placental tissue)", "Hikers", "None"]', 1, 'Presents as a flu-like illness or culture-negative endocarditis. (Harrison''s Ch. 191)'),
    (v_topic_id, '71: "Syphilis" is caused by Treponema pallidum. Primary syphilis is characterized by a/an ____ chancre.', '["Painful", "Painless", "Itchy", "None"]', 1, 'Heals spontaneously but the infection persists. (Harrison''s Ch. 182)'),
    (v_topic_id, '72: Secondary Syphilis classically presents with a rash on the ____ and ____.', '["Face; Neck", "Palms; Soles", "Back; Chest", "None"]', 1, 'Also associated with Condyloma lata. (Step-Up)'),
    (v_topic_id, '73: "Argyll Robertson Pupil" (accommodates but doesn''t react to light) is a sign of:', '["Neurosyphilis (Tabes Dorsalis)", "Stroke", "Glaucoma", "None"]', 0, 'Classic sign of late-stage syphilis. (Pocket Medicine)'),
    (v_topic_id, '74: "Lyme Disease" is caused by Borrelia burgdorferi and is transmitted by the ____ tick.', '["Dermacentor (Dog)", "Ixodes (Deer)", "Lone Star", "None"]', 1, 'Most common vector-borne disease in the US. (Harrison''s Ch. 186)'),
    (v_topic_id, '75: "Erythema Migrans" (target/bull''s-eye rash) is the hallmark of ____ stage Lyme disease.', '["Early localized", "Early disseminated", "Late", "Chronic"]', 0, 'Often accompanied by flu-like symptoms. (Step-Up)'),
    (v_topic_id, '76: Facial nerve (Bell''s) palsy, especially if BILATERAL, is suggestive of which stage of Lyme disease?', '["Early localized", "Early disseminated", "Late", "None"]', 1, 'Stage 2 also involves heart block and meningitis. (Pocket Medicine)'),
    (v_topic_id, '77: What is the first-line antibiotic for Lyme disease in non-pregnant adults and children > 8?', '["Penicillin", "Doxycycline", "Amoxicillin", "Ciprofloxacin"]', 1, 'Amoxicillin is used for children < 8 and pregnant women. (Harrison''s Ch. 186)'),
    (v_topic_id, '78: "Rocky Mountain Spotted Fever" (RMSF) is caused by Rickettsia rickettsii. The rash classically starts on the ____ and spreads ____.', '["Trunk; Outward", "Wrists/Ankles; Inward (centripetal)", "Face; Down", "None"]', 1, 'A medical emergency; treat with Doxycycline immediately. (Step-Up)'),
    (v_topic_id, '79: "Mycoplasma pneumoniae" (Walking Pneumonia) is unique because it lacks a ____.', '["DNA", "Cell wall", "Nucleus", "Ribosomes"]', 1, 'Therefore, it does NOT show up on Gram stain and is resistant to Beta-lactams. (Pocket Medicine)'),
    (v_topic_id, '80: Mycoplasma pneumoniae is associated with which hematologic finding?', '["Anemia", "Cold Agglutinins (IgM antibodies)", "Leukemia", "None"]', 1, 'Can cause autoimmune hemolytic anemia. (Harrison''s Ch. 189)'),
    (v_topic_id, '81: "Jarisch-Herxheimer Reaction" is a fever/chill response that occurs after starting treatment for:', '["Lyme", "Syphilis", "Malaria", "Both Lyme and Syphilis"]', 3, 'Due to the release of endotoxins from dying spirochetes. (Step-Up)'),
    (v_topic_id, '82: "Waterhouse-Friderichsen Syndrome" is adrenal hemorrhage caused by fulminant:', '["Staph aureus", "Neisseria meningitidis (Meningococcemia)", "E. coli", "None"]', 1, 'Leads to acute adrenal insufficiency and shock. (Pocket Medicine)'),
    (v_topic_id, '83: "Cat Scratch Disease" lymphadenopathy is treated with which antibiotic if severe?', '["Penicillin", "Azithromycin", "Ciprofloxacin", "None"]', 1, 'Most cases are self-limiting. (Harrison''s Ch. 172)'),
    (v_topic_id, '84: "HACEK" group endocarditis is best treated with:', '["Penicillin", "Ceftriaxone", "Vancomycin", "None"]', 1, 'They are Gram-negative bacilli. (Step-Up)'),
    (v_topic_id, '85: "Pasteurella" from a cat bite is highly sensitive to:', '["Macrolides", "Penicillins (e.g., Amoxicillin-Clavulanate)", "Aminoglycosides", "None"]', 1, 'Avoid First-generation cephalosporins. (Pocket Medicine)'),
    (v_topic_id, '86: "Ehrlichiosis" and "Anaplasmosis" are tick-borne diseases that cause leukopenia, thrombocytopenia, and elevated LFTs. Treatment is:', '["Penicillin", "Doxycycline", "Acyclovir", "None"]', 1, '"White cells" (Ehrlichia) vs "Platelets" (Anaplasma). (Harrison''s Ch. 191)'),
    (v_topic_id, '87: "Malignant Otitis Externa" is a severe infection of the ear canal and skull base in diabetics, caused by:', '["S. aureus", "Pseudomonas aeruginosa", "Candida", "None"]', 1, 'Requires long-term IV antibiotics. (Step-Up)'),
    (v_topic_id, '88: "Hot Tub Folliculitis" is caused by:', '["Staph", "Pseudomonas aeruginosa", "Fungus", "None"]', 1, 'Self-limiting infection from contaminated water. (Pocket Medicine)'),

    -- SECTION 10-17: PULMONARY, GI, GU, SKIN, BONE
    (v_topic_id, '89: "Community-Acquired Pneumonia" (CAP) is most commonly caused by which organism?', '["Mycoplasma", "Streptococcus pneumoniae", "Haemophilus", "Legionella"]', 1, 'Classic "rusty sputum" and lobar consolidation. (Harrison''s Ch. 135)'),
    (v_topic_id, '90: Which scoring system is used to decide whether a CAP patient needs outpatient, inpatient, or ICU care?', '["SOFA", "CURB-65", "Duke", "Wells"]', 1, 'Confusion, Urea, RR, BP, Age > 65. (Step-Up)'),
    (v_topic_id, '91: "Atypical Pneumonia" (Walking Pneumonia) is most commonly caused by ____ and presents with interstitial infiltrates.', '["S. pneumoniae", "Mycoplasma pneumoniae", "Staph aureus", "None"]', 1, 'Also caused by Chlamydia pneumoniae and Legionella. (Pocket Medicine)'),
    (v_topic_id, '92: "Hospital-Acquired Pneumonia" (HAP) occurs >= ____ hours after admission.', '["12", "24", "48", "72"]', 2, 'Risk factors include mechanical ventilation and poor hand hygiene. (Harrison''s Ch. 135)'),
    (v_topic_id, '93: "Klebsiella pneumoniae" is a common cause of pneumonia in alcoholics and classically presents with ____ sputum.', '["Rusty", "Currant-jelly", "Green", "Bloody"]', 1, 'Thick, mucoid sputum. (Step-Up)'),
    (v_topic_id, '94: Aspiration pneumonia is most commonly caused by ____ and typically involves the ____.', '["Virus; Upper lobes", "Anaerobes; Right lower lobe", "Staph; Left lobe", "None"]', 1, 'Occurs in patients with impaired swallowing or consciousness. (Pocket Medicine)'),
    (v_topic_id, '95: A patient with pneumonia and a history of exposure to BIRDS (e.g., parrots) likely has:', '["Legionella", "Psittacosis (Chlamydia psittaci)", "Q Fever", "Tularemia"]', 1, 'Presents with high fever and splenomegaly. (Harrison''s Ch. 135)'),
    (v_topic_id, '96: "Pneumocystis jirovecii" Pneumonia (PCP) is an opportunistic infection in AIDS patients, classically showing ____ on X-ray.', '["Lobar consolidation", "Diffuse ground-glass / perihilar infiltrates", "Large cavity", "None"]', 1, 'Requires treatment with high-dose TMP-SMX. (Step-Up)'),
    (v_topic_id, '97: PCP prophylaxis is indicated in HIV patients when their CD4 count drops below:', '["500", "200", "100", "50"]', 1, 'TMP-SMX is the drug of choice. (Pocket Medicine)'),
    (v_topic_id, '98: Which physical exam finding suggests "Consolidation" (e.g., pneumonia)?', '["Decreased tactile fremitus", "Increased tactile fremitus and Dullness to percussion", "Hyperresonance", "Wheezing"]', 1, 'Sound travels better through solid (fluid-filled) lung. (Harrison''s Ch. 135)'),
    (v_topic_id, '99: "Mycobacterium tuberculosis" is an acid-fast bacillus. "Primary TB" classically involves the ____ lobes, while "Reactivation TB" involves the ____ lobes.', '["Upper; Lower", "Lower/Middle; Upper", "Right; Left", "None"]', 1, 'Upper lobes are more oxygen-rich, favoring TB growth. (Harrison''s Ch. 176)'),
    (v_topic_id, '100: "Ghon Complex" consists of a calcified lung nodule and a/an ____.', '["Abscess", "Ipsilateral hilar lymph node", "Pleural effusion", "Cavity"]', 1, 'Sign of previous primary TB infection. (Step-Up)'),
    (v_topic_id, '101: A "Positive PPD" test measures which type of hypersensitivity reaction?', '["Type I", "Type II", "Type III", "Type IV (Delayed-type)"]', 3, 'Mediated by T-cells. (Pocket Medicine)'),
    (v_topic_id, '102: "Miliary TB" refers to ____ spread of the bacteria, showing "millet seed" nodules on X-ray.', '["Direct", "Hematogenous (blood-borne)", "Lymphatic", "None"]', 1, 'Can involve almost any organ (liver, spleen, marrow). (Harrison''s Ch. 176)'),
    (v_topic_id, '103: "Pott''s Disease" refers to TB involving the:', '["Kidneys", "Spine", "Liver", "Brain"]', 1, 'Causes vertebral destruction and potentially paralysis. (Step-Up)'),
    (v_topic_id, '104: What is the standard 4-drug regimen (RIPE) for active TB treatment?', '["Rifampin, Insulin, Penicillin, Ethambutol", "Rifampin, Isoniazid, Pyrazinamide, Ethambutol", "Rifampin, Isoniazid, Penicillin, Streptomycin", "None"]', 1, 'Initial phase lasts 2 months. (Pocket Medicine)'),
    (v_topic_id, '105: Which TB drug is most notorious for causing Peripheral Neuropathy (prevented by Vitamin B6)?', '["Rifampin", "Isoniazid (INH)", "Pyrazinamide", "Ethambutol"]', 1, 'INH interferes with B6 (pyridoxine) metabolism. (Harrison''s Ch. 176)'),
    (v_topic_id, '106: Which TB drug can cause "Optic Neuritis" (red-green color blindness)?', '["Rifampin", "Isoniazid", "Pyrazinamide", "Ethambutol"]', 3, '"E" for "E"yes. (Step-Up)'),
    (v_topic_id, '107: "Rifampin" is a potent inducer of the P450 system and characteristically turns body fluids:', '["Blue", "Orange", "Green", "Black"]', 1, 'Benign side effect; warn the patient! (Pocket Medicine)'),
    (v_topic_id, '108: A "Positive IGRA" (Interferon-Gamma Release Assay) is preferred over PPD in patients who have received:', '["Antibiotics", "BCG Vaccine", "Steroids", "None"]', 1, 'BCG can cause a false-positive PPD but not IGRA. (Harrison''s Ch. 176)'),
    (v_topic_id, '109: "Infectious Diarrhea" with blood and mucus (Dysentery) is most commonly caused by ____ or ____.', '["Giardia; Rotavirus", "Shigella; Campylobacter", "Cholera; ETEC", "None"]', 1, 'Indicates invasive disease. (Harrison''s Ch. 141)'),
    (v_topic_id, '110: "Campylobacter jejuni" is a leading cause of bacterial diarrhea and is a major trigger for which neurological condition?', '["Stroke", "Guillain-Barre Syndrome", "MS", "Parkinson''s"]', 1, 'Molecular mimicry between bacterial LPS and gangliosides. (Step-Up)'),
    (v_topic_id, '111: Diarrhea following the consumption of raw SEAFOOD is classically associated with:', '["Salmonella", "Vibrio parahaemolyticus", "E. coli", "Giardia"]', 1, 'V. vulnificus can cause severe cellulitis in patients with liver disease. (Pocket Medicine)'),
    (v_topic_id, '112: "Enterotoxigenic E. coli" (ETEC) is the most common cause of:', '["Bloody diarrhea", "Traveler''s Diarrhea (watery)", "Hemolytic Uremic Syndrome", "None"]', 1, 'Due to heat-labile (LT) and heat-stable (ST) toxins. (Harrison''s Ch. 162)'),
    (v_topic_id, '113: "Enterohemorrhagic E. coli" (EHEC / O157:H7) should NOT be treated with antibiotics because it may increase the risk of:', '["Fever", "Hemolytic Uremic Syndrome (HUS)", "Constipation", "Liver failure"]', 1, 'Antibiotics increase Shiga toxin release. (Step-Up)'),
    (v_topic_id, '114: "Typhoid Fever" (Salmonella Typhi) classically presents with "Rose spots" on the abdomen and:', '["Tachycardia", "Relative Bradycardia (Faget sign)", "High WBC count", "Diarrhea in all cases"]', 1, 'Often involves constipation early on and a "step-ladder" fever. (Pocket Medicine)'),
    (v_topic_id, '115: "Giardia lamblia" causes foul-smelling, fatty diarrhea (steatorrhea) and is often acquired from:', '["Raw eggs", "Mountain stream water (camping/hiking)", "Raw pork", "Air"]', 1, 'Cysts are resistant to chlorine. (Harrison''s Ch. 226)'),
    (v_topic_id, '116: "Spontaneous Bacterial Peritonitis" (SBP) in a patient with cirrhosis is defined by an ascitic fluid absolute neutrophil count (ANC) >= ____.', '["100", "250", "500", "1000"]', 1, 'Commonly caused by E. coli or Klebsiella. (Step-Up)'),
    (v_topic_id, '117: What is the most common cause of "Food Poisoning" with symptoms starting within 1-6 hours (vomiting)?', '["Salmonella", "Staphylococcus aureus (preformed toxin)", "E. coli", "Listeria"]', 1, 'Associated with potato salad, mayonnaise, or custards. (Pocket Medicine)'),
    (v_topic_id, '118: "B. cereus" food poisoning with rapid vomiting is classically associated with:', '["Raw fish", "Reheated Fried Rice", "Raw milk", "Apples"]', 1, 'Spores survive cooking and germinate when rice is left out. (Harrison''s Ch. 156)'),
    (v_topic_id, '119: What is the most common cause of UTIs (Cystitis and Pyelonephritis)?', '["Staph saprophyticus", "Escherichia coli", "Proteus", "Klebsiella"]', 1, 'Responsible for ~80% of outpatient cases. (Harrison''s Ch. 145)'),
    (v_topic_id, '120: "Staphylococcus saprophyticus" is a common cause of UTI in which specific population?', '["Elderly men", "Young, sexually active women", "Hospitalized patients", "Infants"]', 1, 'Second most common cause in this group. (Step-Up)'),
    (v_topic_id, '121: "Pyelonephritis" is distinguished from simple cystitis by the presence of:', '["Painful urination", "Fever, flank pain, and CVA tenderness", "Frequency", "None"]', 1, 'Requires longer antibiotic courses. (Pocket Medicine)'),
    (v_topic_id, '122: "WBC Casts" in the urine are a hallmark of:', '["Cystitis", "Pyelonephritis", "Kidney stones", "Diabetes"]', 1, 'Indicates the infection has reached the renal tubules. (Harrison''s Ch. 145)'),
    (v_topic_id, '123: A UTI with an alkaline urine pH (> 7.0) suggests which organism?', '["E. coli", "Proteus mirabilis", "Candida", "None"]', 1, 'Urease-producing bacteria split urea into ammonia. (Step-Up)'),
    (v_topic_id, '124: "Proteus" UTIs are associated with an increased risk of which type of kidney stone?', '["Calcium oxalate", "Struvite (Staghorn) calculi", "Uric acid", "Cystine"]', 1, 'Stones are composed of magnesium ammonium phosphate. (Pocket Medicine)'),
    (v_topic_id, '125: Asymptomatic bacteriuria should ONLY be treated in which two populations?', '["Elderly; Diabetics", "Pregnant women; Patients undergoing urologic procedures", "Men; Children", "None"]', 1, 'Reduces risk of pyelonephritis and premature birth in pregnancy. (Harrison''s Ch. 145)'),
    (v_topic_id, '126: What is the first-line antibiotic for uncomplicated cystitis in a non-pregnant woman?', '["Ciprofloxacin", "Nitrofurantoin or TMP-SMX", "Penicillin", "Vancomycin"]', 1, 'Nitrofurantoin is preferred if resistance is low. (Step-Up)'),
    (v_topic_id, '127: "Honeymoon Cystitis" refers to UTIs triggered by:', '["Eating too much honey", "Sexual intercourse", "Stress", "None"]', 1, 'Due to mechanical introduction of bacteria into the urethra. (Pocket Medicine)'),
    (v_topic_id, '128: Recurrent UTIs in an older man should prompt an evaluation for:', '["Prostate enlargement / Chronic prostatitis", "Lung cancer", "Diabetes only", "None"]', 0, 'Incomplete bladder emptying. (Harrison''s Ch. 145)'),
    (v_topic_id, '129: What is the most common BACTERIAL STI worldwide?', '["Gonorrhea", "Chlamydia trachomatis", "Syphilis", "Trichomoniasis"]', 1, 'Often asymptomatic but can lead to PID. (Step-Up)'),
    (v_topic_id, '130: "Chlamydia" and "Gonorrhea" are often co-infectants; what is the standard empiric treatment for both?', '["Penicillin + Azithromycin", "Ceftriaxone + Doxycycline", "Vancomycin + Cipro", "None"]', 1, 'Ceftriaxone (IM) for Gonorrhea, Doxycycline (Oral) for Chlamydia. (Pocket Medicine)'),
    (v_topic_id, '131: "Pelvic Inflammatory Disease" (PID) presents with abdominal pain, cervical motion tenderness, and:', '["Fever and discharge", "Blindness", "Cough", "None"]', 0, 'Risk of infertility and ectopic pregnancy. (Harrison''s Ch. 146)'),
    (v_topic_id, '132: "Fitz-Hugh-Curtis Syndrome" is a complication of PID involving inflammation of the:', '["Liver capsule (perihepatitis)", "Spleen", "Heart", "Lungs"]', 0, 'Classic "violin-string" adhesions. (Step-Up)'),
    (v_topic_id, '133: "Trichomonas vaginalis" is a protozoan that causes a "strawberry cervix" and a ____ vaginal discharge.', '["White and thick", "Frothy, yellow-green and foul-smelling", "Clear", "Bloody"]', 1, 'Treated with Metronidazole for both partners. (Pocket Medicine)'),
    (v_topic_id, '134: "Bacterial Vaginosis" (BV) is caused by an overgrowth of Gardnerella vaginalis and shows ____ cells on wet mount.', '["Blast", "Clue cells (epithelial cells covered in bacteria)", "Smudge", "None"]', 1, 'Associated with a "fishy odor" (positive Whiff test). (Harrison''s Ch. 146)'),
    (v_topic_id, '135: "Lymphogranuloma Venereum" (LGV) is caused by specific strains of Chlamydia and presents with painful ____.', '["Rash", "Inguinal lymphadenopathy (buboes)", "Eye infection", "None"]', 1, 'Can also cause proctitis. (Step-Up)'),
    (v_topic_id, '136: "Chancroid" is caused by Haemophilus ducreyi and presents with a ____ genital ulcer.', '["Painless", "Painful", "Itchy", "None"]', 1, '"Ducreyi" = "Do cry" because it''s painful. (Pocket Medicine)'),
    (v_topic_id, '137: "Cellulitis" is a deep skin infection most commonly caused by ____ or ____.', '["E. coli; Pseudomonas", "Streptococcus pyogenes; Staphylococcus aureus", "Fungus", "None"]', 1, 'Presents with redness, warmth, and swelling. (Harrison''s Ch. 136)'),
    (v_topic_id, '138: "Non-purulent" cellulitis is usually treated empirically with coverage for:', '["MRSA", "Streptococcus", "Pseudomonas", "Anaerobes"]', 1, 'If purulent (abscess), MRSA coverage is required. (Step-Up)'),
    (v_topic_id, '139: "Necrotizing Fasciitis" is a surgical emergency. The "Type I" form is ____ while "Type II" is ____.', '["Fungal; Viral", "Polymicrobial; Monomicrobial (Group A Strep)", "Slow; Fast", "None"]', 1, 'Requires immediate debridement and broad antibiotics. (Pocket Medicine)'),
    (v_topic_id, '140: A patient with "pain out of proportion to exam" and gas in the tissues on X-ray likely has:', '["Simple cellulitis", "Necrotizing Fasciitis", "Dermatitis", "None"]', 1, 'High mortality if not treated quickly. (Harrison''s Ch. 136)'),
    (v_topic_id, '141: "Folliculitis" is an infection of the hair follicle, often caused by:', '["S. aureus", "Pseudomonas (in hot tubs)", "Both", "None"]', 2, 'Common and usually self-limiting. (Step-Up)'),
    (v_topic_id, '142: A "Carbuncle" is a/an:', '["Single abscess", "Cluster of interconnected furuncles (abscesses)", "Viral rash", "None"]', 1, 'Typically requires drainage and antibiotics. (Pocket Medicine)'),
    (v_topic_id, '143: "Impetigo" with "honey-colored crusts" is common in children and caused by:', '["Staph and Strep", "Pseudomonas", "Virus", "None"]', 0, 'Highly contagious. (Harrison''s Ch. 136)'),
    (v_topic_id, '144: "Staphylococcal Scalded Skin Syndrome" (SSSS) is caused by an exfoliative toxin and differs from TEN because:', '["It involves the mouth", "It is deeper", "The split is more superficial (subcorneal)", "It is caused by drugs"]', 2, 'TEN (Toxic Epidermal Necrolysis) is a drug reaction. (Step-Up)'),
    (v_topic_id, '145: "Ecthyma" is a deeper form of impetigo that results in:', E'["Scarring", "Ulcers with \\"punched-out\\" appearance", "Blindness", "None"]', 1, 'Often seen in the elderly or neglected patients. (Pocket Medicine)'),
    (v_topic_id, '146: Which organism is a common cause of cellulitis in patients with exposure to FRESH water?', '["S. aureus", "Aeromonas hydrophila", "Vibrio", "None"]', 1, 'Often follows trauma in lakes or rivers. (Harrison''s Ch. 136)'),
    (v_topic_id, '147: What is the most common cause of "Osteomyelitis" (bone infection) overall?', '["Streptococcus", "Staphylococcus aureus", "Salmonella", "Pseudomonas"]', 1, 'Can occur via hematogenous spread or direct inoculation. (Step-Up)'),
    (v_topic_id, '148: Osteomyelitis in a patient with Sickle Cell Disease is classically associated with:', '["Staph", "Salmonella", "E. coli", "None"]', 1, 'High-yield board association. (Pocket Medicine)'),
    (v_topic_id, '149: "Vertebral Osteomyelitis" in an adult is often caused by hematogenous spread from the:', '["Lungs", "Urinary tract or skin", "Brain", "None"]', 1, 'Requires MRI for diagnosis. (Harrison''s Ch. 137)'),
    (v_topic_id, '150: "Septic Arthritis" (infection of the joint space) is a medical emergency; what is the most common cause in young, sexually active adults?', '["S. aureus", "Neisseria gonorrhoeae", "Streptococcus", "None"]', 1, 'Presents as migratory polyarthralgia or monoarthritis. (Step-Up)'),
    (v_topic_id, '151: The gold standard for diagnosing septic arthritis is:', '["X-ray", "Joint aspiration (Arthrocentesis) with cell count and culture", "MRI", "Blood cultures"]', 1, 'WBC count usually > 50,000 cells/mm3. (Pocket Medicine)'),
    (v_topic_id, '152: "Prosthetic Joint Infection" occurring within 3 months of surgery is usually caused by ____, while later infections are caused by ____.', '["Virus; Bacteria", "S. aureus; Coagulase-negative Staph (e.g., S. epidermidis)", "Fungus; Virus", "None"]', 1, 'Biofilm formation is a major challenge. (Harrison''s Ch. 137)'),
    (v_topic_id, '153: What is the treatment for "Chronic Osteomyelitis"?', '["Antibiotics only", "Surgical debridement + long-term antibiotics", "Splinting", "None"]', 1, 'Antibiotics cannot reach necrotic bone (sequestrum). (Step-Up)'),
    (v_topic_id, '154: A patient with a puncture wound through a SNEAKER is at risk for osteomyelitis caused by:', '["Staph", "Pseudomonas aeruginosa", "Salmonella", "None"]', 1, 'Pseudomonas thrives in the moist environment of the shoe sole. (Pocket Medicine)'),
    (v_topic_id, '155: "Reactive Arthritis" (Reiter''s Syndrome) follows an infection (GI or GU) and is characterized by the triad of:', '["Fever, Rash, Pain", "Urethritis, Uveitis, and Arthritis", "Blindness, Deafness, Pain", "None"]', 1, '"Can''t see, can''t pee, can''t climb a tree." (Harrison''s Ch. 137)'),
    (v_topic_id, '156: "Lyme Arthritis" classically presents in the ____ stage and typically affects the ____.', '["Early; Wrists", "Late; Large joints (e.g., Knee)", "Early; Ankles", "None"]', 1, 'Can be chronic if not treated early. (Step-Up)'),
    (v_topic_id, '157: "Brucellosis" is often acquired from:', '["Unpasteurized dairy", "Fresh water", "Soil", "Air"]', 0, 'Presents with "undulant" fever. (Pocket Medicine)'),
    (v_topic_id, '158: "Anthrax" (Bacillus anthracis) inhalation classically causes:', '["Pneumonia", "Hemorrhagic Mediastinitis", "Liver failure", "None"]', 1, 'Look for widened mediastinum on X-ray. (Harrison''s Ch. 156)'),
    (v_topic_id, '159: "Tularemia" (Francisella tularensis) is often associated with contact with:', '["Rabbits", "Dogs", "Birds", "Fish"]', 0, 'Can cause an ulceroglandular syndrome. (Step-Up)'),
    (v_topic_id, '160: "Plague" (Yersinia pestis) is transmitted by:', '["Mosquitoes", "Fleas (from rodents)", "Ticks", "Bites"]', 1, 'Bubonic plague causes painful lymph nodes (buboes). (Pocket Medicine)'),
    (v_topic_id, '161: "Q Fever" (Coxiella burnetii) is often seen in:', '["Fishermen", "Farmers/Veterinarians", "Hikers", "None"]', 1, 'Acquired from livestock birth products. (Harrison''s Ch. 191)'),
    (v_topic_id, '162: "Leptospirosis" can cause "Weil''s Disease," which includes:', '["Fever only", "Jaundice and Renal Failure", "Blindness", "None"]', 1, 'Acquired from water contaminated with animal urine. (Step-Up)'),
    (v_topic_id, '163: "Actinomyces" classically causes abscesses with ____.', '["Black spots", "Sulfur granules", "White discharge", "None"]', 1, 'Anaerobic, branching Gram-positive rod. (Pocket Medicine)'),
    (v_topic_id, '164: "Nocardia" is an acid-fast branching rod that causes infection in the:', '["Lungs and Brain", "Liver", "Bladder", "None"]', 0, 'Often affects immunocompromised patients. (Harrison''s Ch. 180)'),
    (v_topic_id, '165: "Tetanus" toxin blocks ____ neurotransmitters, while "Botulinum" toxin blocks ____.', '["Inhibitory; Excitatory (ACh)", "Excitatory; Inhibitory", "Both; Both", "None"]', 0, 'Spastic vs Flaccid paralysis. (Step-Up)'),
    (v_topic_id, '166: "C. diff" toxins are Toxin A (Enterotoxin) and Toxin B (____).', '["Neurotoxin", "Cytotoxin", "Hepatotoxin", "None"]', 1, 'Toxin B is more potent. (Pocket Medicine)'),
    (v_topic_id, '167: "H. pylori" is a major cause of peptic ulcers and is a risk factor for:', '["Gastric Adenocarcinoma and MALT Lymphoma", "Colon CA", "Liver CA", "None"]', 0, 'Urease-positive Gram-negative rod. (Harrison''s Ch. 173)'),
    (v_topic_id, '168: "Whipple''s Disease" is caused by Tropheryma whipplei and presents with diarrhea, weight loss, and:', '["Joint pain", "Vision loss", "Hearing loss", "None"]', 0, 'PAS-positive macrophages in the lamina propria. (Step-Up)'),
    (v_topic_id, '169: "Rat Bite Fever" is caused by:', '["Streptobacillus moniliformis", "Pasteurella", "Bartonella", "None"]', 0, 'Presents with fever, rash, and joint pain. (Pocket Medicine)'),
    (v_topic_id, '170: "Orf" is a viral skin infection acquired from:', '["Cats", "Sheep/Goats", "Dogs", "Birds"]', 1, 'Presents as a localized nodule on the hand. (Harrison''s Ch. 200)'),
    (v_topic_id, '171: "Ehrlichiosis" shows morulae (mulberry-like inclusions) in ____, while "Anaplasmosis" shows them in ____.', '["Monocytes; Neutrophils", "Neutrophils; Monocytes", "RBCs; WBCs", "None"]', 0, 'Both are tick-borne and treated with Doxycycline. (Step-Up)'),
    (v_topic_id, '172: "Lyme Disease" - Stage 1 is ____, Stage 2 is ____, Stage 3 is ____.', '["Rash; Heart/Nerve; Arthritis", "Arthritis; Rash; Heart", "Heart; Rash; Arthritis", "None"]', 0, 'Standard progression. (Pocket Medicine)'),
    (v_topic_id, '173: "Syphilis" - Primary is ____, Secondary is ____, Tertiary is ____.', '["Rash; Chancre; Gumma", "Chancre; Rash; Gummas/Neuro", "Gumma; Rash; Chancre", "None"]', 1, 'Chancre = Primary; Rash = Secondary. (Harrison''s Ch. 182)'),
    (v_topic_id, '174: "Mycoplasma" causes a/an ____ reaction on blood testing.', '["Agglutination", "Cold Agglutinin (IgM)", "Precipitation", "None"]', 1, 'Useful diagnostic clue. (Step-Up)'),
    (v_topic_id, '175: "Chlamydia" life cycle involves ____ bodies (infectious) and ____ bodies (replicative).', '["Elementary; Reticulate", "Reticulate; Elementary", "Blast; Mature", "None"]', 0, 'Intracellular bacteria. (Pocket Medicine)'),
    (v_topic_id, '176: "Rickettsia" infections (like RMSF) are unique because the rash often starts on the:', '["Trunk", "Wrists and Ankles", "Face", "Neck"]', 1, 'Spreads centripetally. (Harrison''s Ch. 191)'),

    -- SECTION 18-25: HIV, VIRAL, FUNGAL, PARASITIC
    (v_topic_id, '177: HIV infects which type of immune cell by binding to the CD4 receptor and CCR5/CXCR4 co-receptors?', '["B-lymphocytes", "CD4+ T-lymphocytes (Helper T-cells)", "Neutrophils", "Natural Killer cells"]', 1, 'Leads to progressive immune depletion. (Harrison''s Ch. 202)'),
    (v_topic_id, '178: "Acute HIV Syndrome" presents 2-4 weeks after exposure with flu-like symptoms and:', '["Painless chancre", "Generalized lymphadenopathy and maculopapular rash", "Blindness", "None"]', 1, 'Often mistaken for infectious mononucleosis. (Step-Up)'),
    (v_topic_id, '179: A diagnosis of AIDS is made when an HIV-positive patient has a CD4 count < ____ or an AIDS-defining illness.', '["500", "350", "200", "50"]', 2, 'Severe immunosuppression. (Pocket Medicine)'),
    (v_topic_id, '180: Which AIDS-defining opportunistic infection is characterized by white, non-scrapable plaques on the lateral tongue?', '["Oral Thrush (Candida)", "Oral Hairy Leukoplakia (EBV)", "Kaposi Sarcoma", "HSV"]', 1, 'Candida can be scraped off; Hairy Leukoplakia cannot. (Harrison''s Ch. 202)'),
    (v_topic_id, '181: "Kaposi Sarcoma" in HIV is caused by which virus?', '["EBV", "HHV-8", "HPV", "CMV"]', 1, 'Presents as purple/red nodules on the skin or mucous membranes. (Step-Up)'),
    (v_topic_id, '182: "Toxoplasmosis" in AIDS typically presents with multiple ____-enhancing lesions on brain MRI.', '["Non", "Ring", "Linear", "None"]', 1, 'Treated with pyrimethamine and sulfadiazine. (Pocket Medicine)'),
    (v_topic_id, '183: "Cryptosporidiosis" in AIDS causes which severe symptom?', '["Cough", "Chronic, profuse watery diarrhea", "Headache", "Rash"]', 1, 'Can lead to massive fluid loss. (Harrison''s Ch. 202)'),
    (v_topic_id, '184: "Mycobacterium avium complex" (MAC) prophylaxis was traditionally indicated when CD4 count dropped below:', '["200", "100", "50", "20"]', 2, 'Azithromycin is used if the patient is NOT on ART. (Step-Up)'),
    (v_topic_id, '185: "Cytomegalovirus" (CMV) retinitis in AIDS patients presents with blurred vision and a "pizza pie" appearance on fundoscopy; the treatment is:', '["Acyclovir", "Ganciclovir or Foscarnet", "Fluconazole", "None"]', 1, 'Highly aggressive; can lead to blindness. (Pocket Medicine)'),
    (v_topic_id, '186: "Highly Active Antiretroviral Therapy" (HAART) usually consists of ____ drugs from at least ____ different classes.', '["2; 1", "3; 2", "4; 3", "None"]', 1, 'Standard initial regimen involves 2 NRTIs + 1 Integrase Inhibitor. (Harrison''s Ch. 202)'),
    (v_topic_id, '187: "Hepatitis A" is transmitted via the ____ route and does NOT cause chronic infection.', '["Blood-borne", "Fecal-oral", "Sexual", "Aerosol"]', 1, 'Often associated with contaminated food or water. (Step-Up)'),
    (v_topic_id, '188: Which Hepatitis B marker is the FIRST to appear in the blood during acute infection?', '["HBeAg", "HBsAg (Surface Antigen)", "Anti-HBs", "Anti-HBc"]', 1, 'Presence for >6 months defines chronic infection. (Pocket Medicine)'),
    (v_topic_id, '189: "Hepatitis B Surface Antibody" (Anti-HBs) indicates:', '["Acute infection", "Immunity (via vaccination or recovery)", "Chronic carrier", "None"]', 1, 'This is the only positive marker in a successfully vaccinated person. (Harrison''s Ch. 337)'),
    (v_topic_id, '190: "Anti-HBc" (Core Antibody) is positive in both active and recovered patients, but NOT in ____ patients.', '["Chronic", "Vaccinated", "Acute", "None"]', 1, 'Vaccines only contain the surface antigen (HBsAg). (Step-Up)'),
    (v_topic_id, '191: "Hepatitis D" (Delta virus) is a defective virus that requires the presence of ____ to replicate.', '["Hepatitis A", "Hepatitis B (specifically HBsAg)", "Hepatitis C", "HIV"]', 1, 'Can occur as a co-infection or super-infection. (Pocket Medicine)'),
    (v_topic_id, '192: "Hepatitis C" is primarily transmitted via ____ and has a very high rate of progression to chronic infection (>80%).', '["Fecal-oral", "Blood (e.g., IV drug use, previous transfusions)", "Sexual", "Saliva"]', 1, 'Now curable with Direct-Acting Antivirals (DAAs). (Harrison''s Ch. 337)'),
    (v_topic_id, '193: "Hepatitis E" is similar to Hepatitis A but is particularly dangerous (high mortality) in which population?', '["Elderly", "Pregnant women", "Children", "Infants"]', 1, 'Can cause fulminant hepatic failure in pregnancy. (Step-Up)'),
    (v_topic_id, '194: A "Window Period" in Hepatitis B refers to the time when HBsAg has disappeared but ____ has not yet appeared.', '["HBeAg", "Anti-HBs", "Anti-HBc", "None"]', 1, 'Only Anti-HBc IgM might be detectable during this time. (Pocket Medicine)'),
    (v_topic_id, '195: Chronic Hepatitis B and C significantly increase the risk of which cancer?', '["Colon CA", "Hepatocellular Carcinoma (HCC)", "Pancreatic CA", "None"]', 1, 'Requires regular screening with Ultrasound and AFP. (Harrison''s Ch. 337)'),
    (v_topic_id, '196: Which serological marker indicates high viral replication and high infectivity in Hepatitis B?', '["HBsAg", "HBeAg (Envelope Antigen)", "Anti-HBs", "None"]', 1, 'Envelope antigen correlates with viral load. (Step-Up)'),
    (v_topic_id, '197: "Herpes Simplex Virus-1" (HSV-1) is classically associated with ____, while HSV-2 is associated with ____.', '["Genital herpes; Cold sores", "Oral herpes (Cold sores); Genital herpes", "Chickenpox; Shingles", "None"]', 1, 'However, either virus can infect either site. (Pocket Medicine)'),
    (v_topic_id, '198: "Tzanck Smear" shows multi-nucleated giant cells and is used to diagnose:', '["HIV", "Herpesviruses (HSV and VZV)", "HPV", "None"]', 1, 'Rarely used now; PCR is the gold standard. (Harrison''s Ch. 192)'),
    (v_topic_id, '199: "Varicella" (Chickenpox) presents with a "dewdrop on a rose petal" rash in ____.', '["A single dermatome", "Successive crops of lesions in different stages", "A linear pattern", "None"]', 1, 'Highly contagious via respiratory droplets. (Step-Up)'),
    (v_topic_id, '200: "Herpes Zoster" (Shingles) is a reactivation of VZV that occurs in a ____ distribution.', '["Generalized", "Dermatomal", "Facial only", "None"]', 1, 'Often accompanied by severe pain (post-herpetic neuralgia). (Pocket Medicine)'),
    (v_topic_id, '201: "Infectious Mononucleosis" is most commonly caused by ____.', '["CMV", "Epstein-Barr Virus (EBV)", "HIV", "Adenovirus"]', 1, 'Triad of fever, pharyngitis, and posterior cervical lymphadenopathy. (Harrison''s Ch. 194)'),
    (v_topic_id, '202: Patients with EBV mononucleosis who are mistakenly treated with Amoxicillin or Ampicillin often develop a/an:', '["Anaphylaxis", "Maculopapular rash", "Liver failure", "Kidney failure"]', 1, 'Classic board association; not a true allergy. (Step-Up)'),
    (v_topic_id, '203: "Monospot Test" (Heterophile antibody test) is used for EBV. If it is NEGATIVE but the patient has a mono-like illness, think of:', '["Staph", "Cytomegalovirus (CMV)", "Strep", "None"]', 1, 'CMV mono is heterophile-negative. (Pocket Medicine)'),
    (v_topic_id, '204: "Cytomegalovirus" (CMV) classically shows which finding on tissue biopsy?', '["Auer rods", "Owl''s Eye inclusion bodies", "Negri bodies", "None"]', 1, 'Large intranuclear inclusions. (Harrison''s Ch. 195)'),
    (v_topic_id, '205: "Roseola Infantum" (Exanthem Subitum) is caused by HHV-6 and presents as high fever for 3-4 days followed by:', '["Blindness", "A rash that appears as the fever breaks", "Seizures only", "None"]', 1, 'The rash typically starts on the trunk. (Step-Up)'),
    (v_topic_id, '206: "Burkitt Lymphoma" and "Nasopharyngeal Carcinoma" are associated with which virus?', '["HPV", "EBV", "HSV", "None"]', 1, 'EBV is oncogenic. (Pocket Medicine)'),
    (v_topic_id, '207: "Influenza" virus undergoes "Antigenic ____" (minor mutations) and "Antigenic ____" (major reassortment causing pandemics).', '["Shift; Drift", "Drift; Shift", "Swap; Drop", "None"]', 1, 'Drift happens every year; Shift is rare. (Harrison''s Ch. 200)'),
    (v_topic_id, '208: "Reye Syndrome" (encephalopathy and liver failure) can occur in children who take ____ during a viral infection (Flu/Chickenpox).', '["Acetaminophen", "Aspirin", "Ibuprofen", "Antibiotics"]', 1, 'Fatal metabolic disorder; avoid aspirin in kids. (Step-Up)'),
    (v_topic_id, '209: "Measles" (Rubeola) is characterized by the 3 C''s: Cough, Coryza, Conjunctivitis, and ____.', '["Coughing", "Koplik spots (blue-white spots on buccal mucosa)", "Ear pain", "None"]', 1, 'Followed by a brick-red rash that starts on the face. (Pocket Medicine)'),
    (v_topic_id, '210: "Mumps" classically presents with painful swelling of the ____ glands.', '["Thyroid", "Parotid", "Adrenal", "None"]', 1, 'Can also cause orchitis (testicular inflammation). (Harrison''s Ch. 200)'),
    (v_topic_id, '211: "Rubella" (German Measles) is usually mild but is highly teratogenic, causing which classic triad in neonates?', '["Rash, Fever, Pain", "Cataracts, Deafness, and Heart defects (PDA)", "Anemia, Jaundice, Fever", "None"]', 1, 'Congenital Rubella Syndrome. (Step-Up)'),
    (v_topic_id, '212: "Parvovirus B19" causes "Erythema Infectiosum" (Fifth Disease), characterized by a ____ rash.', '["Target", "Slapped-cheek", "Vesicular", "None"]', 1, 'Can cause aplastic crisis in patients with Sickle Cell. (Pocket Medicine)'),
    (v_topic_id, '213: "Hand-Foot-Mouth Disease" is most commonly caused by ____.', '["HSV", "Coxsackievirus A", "HPV", "None"]', 1, 'Presents with oral ulcers and vesicles on hands/feet. (Harrison''s Ch. 200)'),
    (v_topic_id, '214: "RSV" (Respiratory Syncytial Virus) is the most common cause of ____ in infants.', '["Pneumonia", "Bronchiolitis", "Croup", "None"]', 1, 'Presents with wheezing and respiratory distress. (Step-Up)'),
    (v_topic_id, '215: "Croup" (Laryngotracheobronchitis) is caused by the Parainfluenza virus and shows a ____ on neck X-ray.', '["Thumbprint sign", "Steeple sign (subglottic narrowing)", "Linear sign", "None"]', 1, 'Presents with a "barking" cough and stridor. (Pocket Medicine)'),
    (v_topic_id, '216: "Rabies" diagnosis on autopsy is confirmed by the presence of ____ in neurons.', '["Auer rods", "Negri bodies", "Owl''s eyes", "None"]', 1, 'Cytoplasmic inclusions in Purkinje cells. (Harrison''s Ch. 200)'),
    (v_topic_id, '217: What is the most common cause of fungal infections (e.g., thrush, vaginitis, diaper rash)?', '["Aspergillus", "Candida albicans", "Cryptococcus", "Histoplasma"]', 1, 'Commensal organism that becomes pathogenic. (Step-Up)'),
    (v_topic_id, '218: "Oral Candidiasis" (Thrush) in a young, healthy person who is NOT on steroids should prompt testing for:', '["Diabetes", "HIV", "Cancer", "None"]', 1, 'Often the first sign of immunosuppression. (Pocket Medicine)'),
    (v_topic_id, '219: "Aspergillus" can cause a/an ____ (fungal ball) in a pre-existing lung cavity (e.g., from old TB).', '["Abscess", "Aspergilloma", "Tumor", "None"]', 1, 'Can cause severe hemoptysis. (Harrison''s Ch. 216)'),
    (v_topic_id, '220: "Allergic Bronchopulmonary Aspergillosis" (ABPA) is a hypersensitivity reaction seen in patients with:', '["Diabetes", "Asthma or Cystic Fibrosis", "HIV", "None"]', 1, 'Presents with eosinophilia and high IgE. (Step-Up)'),
    (v_topic_id, '221: "Mucormycosis" is a life-threatening fungal infection (Rhino-orbital-cerebral) classically seen in:', '["Diabetics with DKA", "Athletes", "Travelers", "None"]', 0, 'Broad, non-septate hyphae with 90-degree branching. (Pocket Medicine)'),
    (v_topic_id, '222: "Histoplasmosis" is endemic to the Ohio and Mississippi River Valleys and is acquired from ____ or ____ droppings.', '["Dog; Cat", "Bird; Bat", "Rat; Mouse", "None"]', 1, 'Found in soil contaminated with guano. (Harrison''s Ch. 211)'),
    (v_topic_id, '223: "Blastomycosis" is common in the Great Lakes region and can cause characteristic ____ lesions.', '["Red rash", "Verrucous (wart-like) skin lesions", "Blisters", "None"]', 1, 'Broad-based budding yeast. (Step-Up)'),
    (v_topic_id, '224: "Coccidioidomycosis" (Valley Fever) is endemic to the ____ US.', '["Southeast", "Southwest (California/Arizona)", "Northeast", "None"]', 1, 'Acquired by inhaling dust containing spherules. (Pocket Medicine)'),
    (v_topic_id, '225: "Sporotrichosis" (Rose Gardener''s Disease) is a subcutaneous fungal infection that follows a ____.', '["Dog bite", "Thorn prick", "Fish scratch", "None"]', 1, 'Causes nodules that spread along lymphatic channels. (Harrison''s Ch. 211)'),
    (v_topic_id, '226: What is the most effective drug for severe, systemic fungal infections (the "big gun")?', '["Fluconazole", "Amphotericin B", "Nystatin", "Griseofulvin"]', 1, '"Ampho-terrible" due to its high toxicity. (Step-Up)'),
    (v_topic_id, '227: "Malaria" is caused by Plasmodium species. Which species is the MOST severe and life-threatening?', '["P. vivax", "P. falciparum", "P. ovale", "P. malariae"]', 1, 'Causes microvascular sequestration and cerebral malaria. (Harrison''s Ch. 224)'),
    (v_topic_id, '228: Malaria is transmitted by the bite of the female ____ mosquito.', '["Aedes", "Anopheles", "Culex", "None"]', 1, 'Diagnosed with thick and thin blood smears. (Step-Up)'),
    (v_topic_id, '229: Patients with ____ or ____ deficiency are partially protected against severe Malaria.', '["Diabetes; Hypertension", "Sickle Cell Trait; G6PD", "Iron; Vitamin C", "None"]', 1, 'Genetic adaptations to endemic malaria. (Pocket Medicine)'),
    (v_topic_id, '230: "Toxoplasma gondii" is most commonly transmitted to humans via:', '["Dog bites", "Cat feces or undercooked meat", "Aerosols", "None"]', 1, 'Dangerous in pregnancy and AIDS. (Harrison''s Ch. 229)'),
    (v_topic_id, '231: "Entamoeba histolytica" causes bloody diarrhea and classically causes a/an ____ in the liver.', '["Hydatid cyst", "Amoebic Liver Abscess (Anchovy paste appearance)", "Tumor", "None"]', 1, 'Ingestion of cysts from contaminated water. (Step-Up)'),
    (v_topic_id, '232: "Trypanosoma cruzi" causes Chagas Disease in South America, leading to mega-esophagus, mega-colon, and ____.', '["Lung CA", "Dilated Cardiomyopathy", "Blindness", "None"]', 1, 'Transmitted by the "kissing bug" (Reduviid). (Pocket Medicine)'),
    (v_topic_id, '233: "Leishmaniasis" is transmitted by ____ and can cause visceral disease (Kala-azar) or skin ulcers.', '["Fleas", "Sandflies", "Ticks", "Mosquitoes"]', 1, 'Endemic in many tropical regions. (Harrison''s Ch. 227)'),
    (v_topic_id, '234: "Trichomonas vaginalis" discharge is ____, while "Bacterial Vaginosis" is ____.', '["Green/Frothy; Gray/Thin (Fishy)", "Gray; Green", "Clear; Bloody", "None"]', 0, 'Both treated with Metronidazole. (Step-Up)'),
    (v_topic_id, '235: "Amoebic Meningoencephalitis" (the brain-eating amoeba) is caused by ____ after swimming in warm fresh water.', '["Giardia", "Naegleria fowleri", "Toxoplasma", "None"]', 1, 'Rapidly fatal; enters via the nose. (Pocket Medicine)'),
    (v_topic_id, '236: "Babesiosis" is a tick-borne protozoan (Ixodes) that shows a ____ on blood smear.', '["Negri body", "Maltese cross", "Ring form only", "None"]', 1, 'Similar to malaria but in the US (Northeast). (Harrison''s Ch. 225)'),
    (v_topic_id, '237: "Enterobius vermicularis" (Pinworm) causes intense anal itching and is diagnosed with the ____.', '["Blood test", "Scotch Tape test", "Stool culture", "None"]', 1, 'Common in children; treat the whole family. (Step-Up)'),
    (v_topic_id, '238: "Ascaris lumbricoides" is a large roundworm that can cause ____.', '["Blindness", "Intestinal obstruction", "Skin rash only", "None"]', 1, 'The most common helminth infection worldwide. (Pocket Medicine)'),
    (v_topic_id, '239: "Hookworms" (Ancylostoma and Necator) cause ____ because they suck blood from the intestinal wall.', '["Vitamin B12 deficiency", "Iron Deficiency Anemia", "Leukemia", "None"]', 1, 'Larvae penetrate the skin (walking barefoot on soil). (Harrison''s Ch. 232)'),
    (v_topic_id, '240: "Strongyloides stercoralis" can cause a fatal "Hyperinfection syndrome" in patients on ____.', '["Antibiotics", "Glucocorticoids (Steroids)", "Insulin", "None"]', 1, 'Larvae can auto-infect the host. (Step-Up)'),
    (v_topic_id, '241: "Trichinella spiralis" is acquired from undercooked ____ and causes muscle pain and periorbital edema.', '["Fish", "Pork or Bear meat", "Beef", "Chicken"]', 1, 'Larvae encyst in muscle. (Pocket Medicine)'),
    (v_topic_id, '242: "Schistosomiasis" is a fluke infection associated with ____ and can cause portal hypertension or bladder cancer.', '["Raw fish", "Fresh water snails", "Undercooked beef", "None"]', 1, 'Cercariae penetrate the skin while swimming. (Harrison''s Ch. 235)'),
    (v_topic_id, '243: "Taenia solium" (Pork Tapeworm) causes ____ if you eat the eggs, leading to cysts in the brain.', '["Diarrhea", "Neurocysticercosis (seizures)", "Blindness", "None"]', 1, 'Leading cause of seizures in the developing world. (Step-Up)'),
    (v_topic_id, '244: "Echinococcus granulosus" (Dog Tapeworm) causes ____ in the liver.', '["Abscesses", "Hydatid cysts (with daughter cysts)", "Tumors", "None"]', 1, 'Cysts must not be ruptured (risk of anaphylaxis). (Pocket Medicine)'),
    (v_topic_id, '245: "Loa loa" (African eye worm) is transmitted by deer flies and can be seen ____.', '["In the stool", "Crossing the conjunctiva of the eye", "In the ear", "None"]', 1, 'Causes transient "Calabar swellings." (Harrison''s Ch. 233)'),
    (v_topic_id, '246: What is the drug of choice for most flatworm (fluke) and tapeworm infections?', '["Albendazole", "Praziquantel", "Ivermectin", "Mebendazole"]', 1, 'Ivermectin is for "river blindness" and Strongyloides. (Step-Up)'),
    (v_topic_id, '247: "Atypical Lymphocytes" = ?', '["Bacterial sepsis", "EBV / CMV Mononucleosis", "Leukemia", "None"]', 1, 'Reactive T-cells. (Pocket Medicine)'),
    (v_topic_id, '248: "Koplik Spots" = ?', '["Rubella", "Measles (Rubeola)", "Mumps", "None"]', 1, 'Buccal spots. (Harrison''s Ch. 200)'),
    (v_topic_id, '249: "Rusty Sputum" = ?', '["Klebsiella", "Streptococcus pneumoniae", "Legionella", "None"]', 1, 'Pneumococcal pneumonia. (Step-Up)'),
    (v_topic_id, '250: "Currant Jelly Sputum" = ?', '["Strep", "Klebsiella pneumoniae", "Mycoplasma", "None"]', 1, 'Common in alcoholics. (Pocket Medicine)'),
    (v_topic_id, '251: "Slapped-Cheek Rash" = ?', '["Measles", "Parvovirus B19", "Rubella", "None"]', 1, 'Erythema infectiosum. (Harrison''s Ch. 200)'),
    (v_topic_id, '252: "India Ink" positive = ?', '["Candida", "Cryptococcus neoformans", "Aspergillus", "None"]', 1, 'Thick capsule doesn''t take up the ink. (Step-Up)'),
    (v_topic_id, '253: "Maltese Cross" on smear = ?', '["Malaria", "Babesiosis", "Toxoplasmosis", "None"]', 1, 'Tick-borne protozoan. (Pocket Medicine)'),
    (v_topic_id, '254: "Spherules" on biopsy = ?', '["Histo", "Coccidioidomycosis", "Blasto", "None"]', 1, 'Southwest US endemic fungus. (Harrison''s Ch. 212)'),
    (v_topic_id, '255: "Broad-based budding yeast" = ?', '["Histo", "Blastomycosis", "Coccidio", "None"]', 1, 'Great Lakes region. (Step-Up)'),
    (v_topic_id, '256: "Intracellular yeast in macrophages" = ?', '["Coccidio", "Histoplasmosis", "Blasto", "None"]', 1, 'Bird/Bat guano association. (Pocket Medicine)'),
    (v_topic_id, '257: "Gumma" = ?', '["Primary Syphilis", "Tertiary Syphilis", "Secondary Syphilis", "None"]', 1, 'Granulomatous lesion. (Harrison''s Ch. 182)'),
    (v_topic_id, '258: "Condyloma Lata" = ?', '["HPV", "Secondary Syphilis", "HSV", "None"]', 1, 'Flat, broad-based warts. (Step-Up)'),
    (v_topic_id, '259: "Condyloma Acuminatum" = ?', '["Syphilis", "Human Papillomavirus (HPV)", "HIV", "None"]', 1, 'Cauliflower-like warts (types 6 and 11). (Pocket Medicine)'),
    (v_topic_id, '260: "Councilman Bodies" = ?', '["Hepatitis A", "Yellow Fever", "Malaria", "None"]', 1, 'Eosinophilic apoptotic hepatocytes. (Harrison''s Ch. 201)'),
    (v_topic_id, '261: "Guarnieri Bodies" = ?', '["Chickenpox", "Smallpox (Variola)", "Herpes", "None"]', 1, 'Intracytoplasmic inclusions. (Step-Up)'),
    (v_topic_id, '262: "Negri Bodies" = ?', '["Measles", "Rabies", "Mumps", "None"]', 1, 'Purkinje cell inclusions. (Pocket Medicine)'),
    (v_topic_id, '263: "Dewdrop on a rose petal" = ?', '["Measles", "Varicella (Chickenpox)", "Rubella", "None"]', 1, 'Classic description of vesicles. (Harrison''s Ch. 192)'),

    -- SECTION 26-29: ANTIBIOTICS, NOSOCOMIAL, SPRINT
    (v_topic_id, '264: "Beta-lactam" antibiotics (Penicillins, Cephalosporins) work by inhibiting:', '["Protein synthesis", "Cell wall synthesis (Transpeptidation)", "DNA replication", "Folic acid metabolism"]', 1, 'They bind to Penicillin-Binding Proteins (PBPs). (Harrison''s Ch. 144)'),
    (v_topic_id, '265: "Nafcillin" and "Oxacillin" are primarily used to treat which organism?', '["E. coli", "MSSA (Methicillin-Sensitive Staph aureus)", "MRSA", "Pseudomonas"]', 1, 'They are penicillinase-resistant penicillins. (Step-Up)'),
    (v_topic_id, '266: Which generation of Cephalosporins (e.g., Ceftriaxone, Ceftazidime) has the BROADEST Gram-negative coverage and CNS penetration?', '["First", "Second", "Third", "None"]', 2, 'Ceftriaxone is the standard for meningitis and gonorrhea. (Pocket Medicine)'),
    (v_topic_id, '267: "Cefepime" is a 4th-generation cephalosporin with excellent activity against which resistant Gram-negative?', '["MRSA", "Pseudomonas aeruginosa", "VRE", "None"]', 1, 'Combines 1st gen Gram-positive and 3rd gen Gram-negative activity. (Harrison''s Ch. 144)'),
    (v_topic_id, '268: "Carbapenems" (e.g., Meropenem) are the drugs of choice for which type of resistant bacteria?', '["MRSA", "ESBL-producing Gram-negative rods", "VRE", "Mycoplasma"]', 1, 'ESBL = Extended-Spectrum Beta-Lactamase. (Step-Up)'),
    (v_topic_id, '269: "Vancomycin" works by binding to the ____ terminus of peptidoglycan precursors.', '["D-Ala-D-Ala", "D-Ala-D-Ser", "L-Lys", "None"]', 0, 'Inhibits cell wall cross-linking; used for MRSA. (Pocket Medicine)'),
    (v_topic_id, '270: "Red Man Syndrome" is a non-allergic histamine release associated with rapid infusion of:', '["Penicillin", "Vancomycin", "Gentamicin", "Ciprofloxacin"]', 1, 'Prevented by slowing the infusion rate and antihistamines. (Harrison''s Ch. 144)'),
    (v_topic_id, '271: A patient with a severe anaphylactic allergy to Penicillin should generally avoid which other class?', '["Cephalosporins (especially 1st gen)", "Macrolides", "Tetracyclines", "None"]', 0, 'Cross-reactivity is ~1-10% depending on the generation. (Step-Up)'),
    (v_topic_id, '272: "Aztreonam" is a monobactam that is safe to use in patients with penicillin allergy and only covers ____.', '["Gram-positives", "Gram-negatives (including Pseudomonas)", "Anaerobes", "Fungi"]', 1, 'Has no Gram-positive or anaerobic activity. (Pocket Medicine)'),
    (v_topic_id, '273: "Linezolid" is used for VRE and MRSA but can cause which hematologic side effect with prolonged use?', '["Anemia", "Thrombocytopenia", "Leukemia", "None"]', 1, 'Also carries a risk of Serotonin Syndrome if used with SSRIs. (Harrison''s Ch. 144)'),
    (v_topic_id, '274: "Aminoglycosides" (e.g., Gentamicin, Amikacin) are known for causing which two major toxicities?', '["Liver and Lung", "Ototoxicity and Nephrotoxicity", "Bone and Heart", "None"]', 1, 'Require monitoring of peak and trough levels. (Step-Up)'),
    (v_topic_id, '275: "Tetracyclines" (e.g., Doxycycline) are contraindicated in pregnancy and children < 8 because they cause:', '["Blindness", "Discoloration of teeth and inhibition of bone growth", "Liver failure", "None"]', 1, 'They chelate calcium in developing structures. (Pocket Medicine)'),
    (v_topic_id, '276: "Macrolides" (e.g., Azithromycin, Erythromycin) work by binding to the ____ ribosomal subunit.', '["30S", "50S", "60S", "80S"]', 1, 'Bacteriostatic inhibitors of protein synthesis. (Harrison''s Ch. 144)'),
    (v_topic_id, '277: "Clindamycin" is excellent for anaerobic infections but is the most notorious trigger for:', '["Kidney failure", "C. diff colitis", "Hearing loss", "None"]', 1, 'Disrupts colonic flora, allowing C. diff overgrowth. (Step-Up)'),
    (v_topic_id, '278: "Fluoroquinolones" (e.g., Ciprofloxacin, Levofloxacin) inhibit which enzyme?', '["RNA polymerase", "DNA Gyrase (Topoisomerase II/IV)", "Transpeptidase", "None"]', 1, 'Can cause tendon rupture (Achilles) and QTc prolongation. (Pocket Medicine)'),
    (v_topic_id, '279: "Metronidazole" is the drug of choice for anaerobes "below the diaphragm" and causes a ____ reaction with alcohol.', '["None", "Disulfiram-like (severe nausea/vomiting)", "Allergic", "None"]', 1, 'Inhibits acetaldehyde dehydrogenase. (Harrison''s Ch. 144)'),
    (v_topic_id, '280: "Trimethoprim-Sulfamethoxazole" (TMP-SMX) inhibits folic acid synthesis and is a common cause of which severe skin reaction?', '["Acne", "Stevens-Johnson Syndrome (SJS)", "Hives only", "None"]', 1, 'Also causes hyperkalemia and bone marrow suppression. (Step-Up)'),
    (v_topic_id, '281: "Daptomycin" is used for resistant Gram-positives but is inactivated by ____, making it useless for pneumonia.', '["Acid", "Pulmonary Surfactant", "Water", "None"]', 1, 'Used for skin/soft tissue and bacteremia instead. (Pocket Medicine)'),
    (v_topic_id, '282: "Nitrofurantoin" is used primarily for UTIs but can cause which chronic toxicity?', '["Kidney failure", "Pulmonary Fibrosis", "Liver failure", "None"]', 1, 'Can be acute or chronic; check LFTs and chest X-rays if used long-term. (Harrison''s Ch. 144)'),
    (v_topic_id, '283: "Rifampin" is used in TB and as an adjunct for staphylococcal infections on ____.', '["Skin", "Biofilms (e.g., prosthetic valves/joints)", "Lungs", "None"]', 1, 'Excellent penetration into biofilms. (Step-Up)'),
    (v_topic_id, '284: "Fever of Unknown Origin" (FUO) is defined as a fever > 38.3C lasting > ____ weeks without a diagnosis after 1 week of investigation.', '["1", "3", "6", "12"]', 1, 'Classic categories: Infection, Malignancy, Autoimmune. (Harrison''s Ch. 17)'),
    (v_topic_id, '285: In the elderly, the most common "Autoimmune" cause of FUO is:', '["Lupus", "Giant Cell Arteritis / PMR", "RA", "None"]', 1, 'Requires checking ESR/CRP and possibly temporal artery biopsy. (Step-Up)'),
    (v_topic_id, '286: "Ventilator-Associated Pneumonia" (VAP) is minimized by which intervention?', '["Lying flat", "Head-of-bed elevation (30-45 degrees)", "No suctioning", "None"]', 1, 'Prevents microaspiration of gastric/oral contents. (Pocket Medicine)'),
    (v_topic_id, '287: "CLABSI" stands for Central Line-Associated ____ Infection.', '["Bladder", "Bloodstream", "Bone", "None"]', 1, 'Prevented by maximum sterile barriers during insertion. (Harrison''s Ch. 143)'),
    (v_topic_id, '288: What is the most important measure to prevent the spread of nosocomial infections?', '["Wearing masks", "Hand hygiene (soap/water or alcohol rub)", "Giving prophylaxis", "None"]', 1, 'Simple but most effective intervention. (Step-Up)'),
    (v_topic_id, '289: "Standard Precautions" apply to all patients, while "Contact Precautions" (gown/gloves) are specifically for:', '["Flu", "MRSA, VRE, and C. diff", "TB", "None"]', 1, 'C. diff requires soap and water (alcohol doesn''t kill spores). (Pocket Medicine)'),
    (v_topic_id, '290: "Airborne Precautions" (N95 mask, negative pressure room) are required for:', '["Flu", "TB, Measles, and Varicella", "Staph", "None"]', 1, 'Particles remain suspended in the air. (Harrison''s Ch. 143)'),
    (v_topic_id, '291: "Droplet Precautions" (surgical mask) are required for infections like:', '["TB", "Neisseria meningitidis, Influenza, Pertussis", "C. diff", "None"]', 1, 'Large droplets that do not travel beyond 3-6 feet. (Step-Up)'),
    (v_topic_id, '292: "Neutropenic Precautions" (Reverse isolation) are for patients with ANC < ____.', '["500", "1500", "5000", "None"]', 0, 'Avoid fresh flowers, fruits, or live plants. (Pocket Medicine)'),
    (v_topic_id, '293: "Fever + Rash on palms/soles" = ?', '["Measles", "Secondary Syphilis, RMSF, or Coxsackie A", "Lyme", "None"]', 1, 'High-yield clinical triad. (Harrison''s Ch. 141)'),
